insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_music3_v1'
from (values
('117.312.c.1.A',3,'A student attends a live concert and also streams a professional recording, then judges which performance best shows phrasing and balance. She is doing what?','["Evaluating exemplary musical examples", "Printing programs", "Selling tickets", "Tuning a piano"]'::jsonb,0,'She judges models against criteria.','original'),
('117.312.c.1.A',3,'Which statement is an evaluation of a recording?','["It was released on a Friday", "The strings shaped the phrase with a clear dynamic arc", "The cover is red", "It is track four"]'::jsonb,1,'Evaluation addresses musical qualities.','original'),
('117.312.c.1.B',3,'A single unaccompanied melody with no harmony has which texture?','["Heterophony only", "Homophony", "Monophony", "Polyphony"]'::jsonb,2,'Monophony is one melodic line.','original'),
('117.312.c.1.B',3,'A melody with chordal accompaniment has which texture?','["Silence", "Rhythm only", "Monophony", "Homophony"]'::jsonb,3,'Homophony is melody plus chords.','original'),
('117.312.c.1.C',3,'Compare a major seventh chord with a major triad. What is the difference?','["The seventh chord adds a fourth pitch a seventh above the root", "It has fewer notes", "It has no root", "It lacks a third"]'::jsonb,0,'Seventh chords add a fourth tone.','original'),
('117.312.c.1.C',3,'An augmented fourth interval contains how many half steps?','["Eight", "Six", "Eleven", "Three"]'::jsonb,1,'The tritone spans six half steps.','original'),
('117.312.c.1.D',3,'Compare 5/4 and 4/4. What distinguishes 5/4?','["Four beats per measure", "No pulse at all", "Five beats per measure, often grouped unevenly", "Three beats per measure"]'::jsonb,2,'5/4 is an asymmetrical meter.','original'),
('117.312.c.1.D',3,'Syncopation is best described as what?','["Gradual slowing", "Equal accents on every beat", "Constant silence", "Emphasis placed on normally weak beats or off-beats"]'::jsonb,3,'Syncopation shifts accents.','original'),
('117.312.c.1.E',3,'A movement with exposition, development and recapitulation uses which form?','["Sonata-allegro", "Binary", "Strophic", "Rondo"]'::jsonb,0,'Sonata-allegro has three main sections.','original'),
('117.312.c.1.E',3,'How does ternary form differ from rondo form?','["Rondo has two notes", "Ternary has three sections, while a rondo returns to its theme several times", "They are identical", "Ternary has no repeats"]'::jsonb,1,'A rondo''s refrain recurs.','original'),
('117.312.c.1.F',3,'A conductor asks the horns to play softer so the melody in the oboes can be heard. She is adjusting what?','["Notation", "Key", "Balance", "Meter"]'::jsonb,2,'Balance is the relative volume among parts.','original'),
('117.312.c.1.F',3,'Blend is achieved when instruments match what?','["Page numbers", "Costume colors", "Seat height", "Tone color, attack and dynamic level"]'::jsonb,3,'Matching these qualities unifies sound.','original'),
('117.312.c.1.G',3,'A work for solo voices and orchestra with recitatives and arias that tells a staged story is an ___.','["Opera", "Cantata", "Motet", "Rondo"]'::jsonb,0,'Opera combines drama and music.','original'),
('117.312.c.1.G',3,'Zydeco music is associated with which region?','["Northern Siberia", "Southwest Louisiana", "Central Australia", "Southern Argentina"]'::jsonb,1,'Zydeco comes from Creole communities of Louisiana.','original'),
('117.312.c.1.H',3,'Contrasting two pieces'' use of imitation among parts compares which element?','["Seat count", "Program length", "Texture", "Hall acoustics only"]'::jsonb,2,'Imitation among voices is a textural feature.','original'),
('117.312.c.1.H',3,'The pitch center and its major or minor scale form a piece''s what?','["Tempo", "Fermata", "Bar line", "Tonality"]'::jsonb,3,'Tonality organizes pitch.','original'),
('117.312.c.1.I',2,'Frequent exposure to very loud rehearsals without protection may cause what?','["Permanent hearing damage", "Stronger lungs", "Better pitch", "Improved tone"]'::jsonb,0,'Noise-induced hearing loss is preventable.','original'),
('117.312.c.1.I',2,'Which practice habit supports healthy body mechanics?','["Ignoring pain", "Taking short breaks and stretching during long sessions", "Holding tension", "Playing without rest"]'::jsonb,1,'Rest and stretching prevent strain.','original'),
('117.312.c.2.A',3,'A student transcribes a melody she hears into notation by writing pitch and rhythm. What is she using?','["A ticket stub", "A conductor''s baton", "Skills for reading and notating melody and rhythm", "A stage plot"]'::jsonb,2,'Notation records pitch and rhythm.','original'),
('117.312.c.2.A',3,'Which element must a written melody show besides pitch?','["Smell", "Weight", "Color", "Rhythm"]'::jsonb,3,'Melody notation includes durations.','original'),
('117.312.c.2.B',3,'The term cantabile instructs a performer to play how?','["In a singing style", "Very fast", "Very short", "Silently"]'::jsonb,0,'Cantabile means songlike.','original'),
('117.312.c.2.B',3,'What does the marking rit. tell a player to do?','["Gradually get louder", "Gradually slow the tempo", "Repeat the section", "Stop forever"]'::jsonb,1,'Ritardando means slowing.','original'),
('117.312.c.3.A',3,'Which describes a mature tone on a cello?','["Constantly changing", "Very thin", "Rich, even and resonant throughout the range", "Scratchy and uneven"]'::jsonb,2,'Mature tone is controlled and full.','original'),
('117.312.c.3.A',3,'A baritone adjusts vowel shape to match the genre''s expected sound. She is demonstrating what?','["Random tone", "Poor diction", "Rushing", "Characteristic sound appropriate for the genre"]'::jsonb,3,'Tone is style-specific.','original'),
('117.312.c.3.B',3,'A percussionist adjusts stick grip to avoid wrist strain. She is refining what?','["Psychomotor skills", "Program notes", "Ticket sales", "Seating plans"]'::jsonb,0,'Efficient technique prevents strain.','original'),
('117.312.c.3.B',3,'Which technique helps a singer sustain a long phrase?','["Holding the jaw tight", "Low, controlled breath support", "Raising the shoulders", "Gasping"]'::jsonb,1,'Support controls airflow.','original'),
('117.312.c.3.C',3,'A student marks subdivisions in a difficult measure and plays with a metronome. She is working on what?','["Key signature", "Seating", "Rhythmic accuracy", "Phrase shape"]'::jsonb,2,'Subdividing refines timing.','original'),
('117.312.c.3.C',3,'Which tempo choice shows good rhythmic control?','["Speeding up in easy spots", "Changing randomly", "Dragging at every rest", "A steady pulse maintained through the passage"]'::jsonb,3,'Steady pulse is the goal.','original'),
('117.312.c.3.D',3,'A piece in E major has how many sharps?','["Four", "Six", "One", "Zero"]'::jsonb,0,'E major has F, C, G and D sharp.','original'),
('117.312.c.3.D',3,'A relative minor shares what with its major key?','["The same tempo only", "The same key signature", "The same title", "The same clef only"]'::jsonb,1,'Relative keys share signatures.','original'),
('117.312.c.3.E',3,'An alto holds a note slightly sharp against the group. What should she do?','["Sing louder", "Ignore it", "Listen and adjust her pitch to match", "Stop singing"]'::jsonb,2,'Active listening corrects intonation.','original'),
('117.312.c.3.E',3,'Phrasing shapes music by doing what?','["Removing dynamics", "Playing every note equally", "Forbidding breaths", "Grouping notes into musical sentences with direction"]'::jsonb,3,'Phrases give direction.','original'),
('117.312.c.3.F',3,'A student arranges a folk tune for her trio at a level they can perform. She is doing what?','["Creating music at an appropriate difficulty", "Printing tickets", "Avoiding the music", "Buying instruments"]'::jsonb,0,'Arranging fits the players.','original'),
('117.312.c.3.F',3,'Which resource helps share an original composition?','["A parking ticket", "A recording or notation file", "A coupon", "A bus pass"]'::jsonb,1,'Recording or notating preserves music.','original'),
('117.312.c.4.A',3,'Maintaining a mature, characteristic sound while sight reading shows what?','["Panic", "Lack of focus", "Tone control even with unfamiliar notes", "Memorization"]'::jsonb,2,'Tone persists under pressure.','original'),
('117.312.c.4.A',3,'How can a sight reader keep consistent tone?','["Tighten the jaw", "Rush the tempo", "Hold her breath", "Keep air steady and posture open"]'::jsonb,3,'Technique supports tone.','original'),
('117.312.c.4.B',3,'A bassoonist adjusts posture and breathing before sight reading a new piece. She is applying what?','["Psychomotor and kinesthetic skills", "Ticket policy", "Concert dress rules", "Stage plots"]'::jsonb,0,'Preparation uses physical technique.','original'),
('117.312.c.4.B',3,'A relaxed hand position during sight reading helps prevent what?','["Hearing", "Tension and injury", "Counting", "Reading"]'::jsonb,1,'Relaxation protects the body.','original'),
('117.312.c.4.C',3,'Before sight reading, a student checks accents and slurs and mentally counts the rhythm. She is preparing what?','["The lighting", "The lobby", "Articulation and rhythmic accuracy", "The seating chart"]'::jsonb,2,'These are key to accurate reading.','original'),
('117.312.c.4.C',3,'Which strategy helps count rhythms while sight reading?','["Reading only pitches", "Skipping rests", "Ignoring the meter", "Tapping the beat while counting subdivisions aloud"]'::jsonb,3,'Counting systems support accuracy.','original'),
('117.312.c.4.D',3,'A sight-reading piece changes from four flats to two sharps. What must the player do?','["Adjust quickly to the new key signature", "Stop at the change", "Play every note natural", "Ignore it"]'::jsonb,0,'Key changes alter pitches.','original'),
('117.312.c.4.D',3,'Changing modality mid-piece, such as from minor to major, requires attention to what?','["The page color", "New accidentals and the shifted tonal center", "The audience", "The composer''s name"]'::jsonb,1,'Mode changes alter pitches.','original'),
('117.312.c.4.E',3,'Using letter names while reading melody is an example of what?','["A dynamic marking", "A tuning method", "A melodic reading system", "A rhythm pattern"]'::jsonb,2,'Letter names identify pitches.','original'),
('117.312.c.4.E',3,'Which method labels notes with syllables like do, re and mi?','["Bowing marks", "Time signatures", "Metronome clicks", "Solfège"]'::jsonb,3,'Solfège uses syllables.','original'),
('117.312.c.4.F',3,'A sight reader sees p cresc. to f in four measures. How should she play it?','["Begin soft and grow steadily to loud", "Start loud and fade", "Stay soft", "Skip the measures"]'::jsonb,0,'The marking indicates a gradual increase.','original'),
('117.312.c.4.F',3,'What does shaping a phrase while sight reading require?','["Ignoring slurs", "Reading ahead for direction and dynamics", "Playing blindly", "Stopping often"]'::jsonb,1,'Reading ahead supports phrasing.','original'),
('117.312.c.4.G',3,'Matching vowel shapes in a choir while sight reading improves what?','["Notation", "Lyrics", "Intonation", "Meter"]'::jsonb,2,'Unified vowels help pitch.','original'),
('117.312.c.4.G',3,'Which listening habit improves intonation in an ensemble?','["Ignoring neighbors", "Playing louder", "Rushing", "Tuning chords from the bass up"]'::jsonb,3,'Building from the bass stabilizes pitch.','original'),
('117.312.c.5.A',3,'A student sorts recordings into Baroque, Classical and Romantic categories. She is doing what?','["Classifying music by period and style", "Counting seats", "Ordering lunch", "Mixing colors"]'::jsonb,0,'Classification uses historical context.','original'),
('117.312.c.5.A',3,'Which feature suggests a Baroque work?','["Auto-tune", "Ornamented lines and continuo", "Hip-hop beats", "Electronic synthesizers"]'::jsonb,1,'Basso continuo is typical of Baroque music.','original'),
('117.312.c.5.B',3,'Why do many communities hold music festivals?','["To avoid art", "To raise taxes", "To celebrate and share cultural identity", "To ban dancing"]'::jsonb,2,'Festivals express culture.','original'),
('117.312.c.5.B',3,'Work songs historically helped communities by doing what?','["Ending trade", "Banning instruments", "Preventing speech", "Coordinating labor and building solidarity"]'::jsonb,3,'They set rhythm for group work.','original'),
('117.312.c.5.C',3,'Frequency and wavelength in sound connect music with which discipline?','["Physics", "Typing", "Gym", "Cooking"]'::jsonb,0,'Pitch is tied to frequency.','original'),
('117.312.c.5.C',3,'Studying the history of a composer''s era connects music with what subject?','["Driver education", "Social studies", "Welding", "Chemistry lab"]'::jsonb,1,'Music reflects history.','original'),
('117.312.c.5.D',3,'Which career involves designing sound for films and games?','["Lifeguard", "Plumber", "Audio engineer or sound designer", "Surveyor"]'::jsonb,2,'Sound design is a music-related career.','original'),
('117.312.c.5.D',3,'Analyzing a career option in music includes considering what?','["Shoe size", "Favorite food", "Hair color", "Education needed, income potential and job outlook"]'::jsonb,3,'Careers are analyzed by requirements and outlook.','original'),
('117.312.c.5.E',3,'Streaming platforms pay artists small amounts per play. This is an example of what?','["An economic factor affecting musicians", "A dynamic marking", "A key signature", "A rhythm pattern"]'::jsonb,0,'Payment structures impact musicians.','original'),
('117.312.c.5.E',3,'Sampling another artist''s work without permission raises what concern?','["A seating concern", "Ethical and legal questions about ownership", "A tuning concern", "A meter concern"]'::jsonb,1,'Sampling raises rights issues.','original'),
('117.312.c.5.F',3,'A student builds an electronic portfolio with recordings and a résumé. She is generating what?','["A time signature", "A cadence", "Tools for college and career preparation", "A rest"]'::jsonb,2,'Portfolios help auditions and applications.','original'),
('117.312.c.5.F',3,'Which belongs in a professional musician''s electronic portfolio?','["Random photos", "Weather notes", "Receipts for lunch", "Performance videos and a list of repertoire"]'::jsonb,3,'These showcase abilities.','original'),
('117.312.c.6.A',2,'Which action shows good etiquette at a recorded or live performance?','["Remaining quiet and respectful during the music", "Leaving mid-piece", "Texting aloud", "Shouting over performers"]'::jsonb,0,'Respect supports the experience.','original'),
('117.312.c.6.A',2,'As a performer during a rest in the program, you should do what?','["Walk off", "Stay focused and respectful of others onstage", "Chat loudly", "Check phone"]'::jsonb,1,'Focus shows professionalism.','original'),
('117.312.c.6.B',3,'A class writes criteria for judging a jazz combo versus a chamber choir. Why should criteria be specific to style?','["Style does not matter", "Only volume matters", "Each style values different qualities", "All music is the same"]'::jsonb,2,'Different styles have different standards.','original'),
('117.312.c.6.B',3,'Which is a criterion for evaluating a jazz performance?','["Parking", "Ticket price", "Brightness of the lobby", "Quality of improvised solos and rhythmic feel"]'::jsonb,3,'Jazz values improvisation and swing.','original'),
('117.312.c.6.C',3,'A student offers a peer constructive feedback by naming a strength and a specific suggestion. She is doing what?','["Applying criteria for constructive feedback", "Copying a score", "Being rude", "Avoiding comment"]'::jsonb,0,'Constructive feedback is specific.','original'),
('117.312.c.6.C',3,'Which format can be used to give feedback to a peer?','["A coupon", "A written rubric or recorded comments", "A menu", "A bus map"]'::jsonb,1,'Multiple formats are valid.','original'),
('117.312.c.6.D',3,'A musician records weekly, listens critically and picks a metronome app to track goals. She is developing what?','["A concert program", "A lobby display", "A process for self-evaluation", "A ticket log"]'::jsonb,2,'Tools and routines support growth.','original'),
('117.312.c.6.D',3,'Which tool supports artistic improvement?','["A vacation brochure", "A bus pass", "A coupon", "A recorded practice log with goals"]'::jsonb,3,'Logs record progress.','original'),
('117.312.c.6.E',3,'A student compares her ensemble''s performance with an exemplary model and writes recommendations. She is doing what?','["Evaluating performance and offering suggestions", "Hiding the recording", "Skipping rehearsal", "Avoiding feedback"]'::jsonb,0,'Comparison leads to recommendations.','original'),
('117.312.c.6.E',3,'What makes feedback offered after comparing to a model useful?','["It is hurtful", "It is specific and suggests a next step", "It is vague", "It is silent"]'::jsonb,1,'Specific advice helps improvement.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
